select.where:
`tag_ref`.`tag_id` = #{tagId}
AND (`dev`.`device_code` LIKE CONCAT('%',#{query.keyword},'%') OR `dev`.`device_name` LIKE CONCAT('%',#{query.keyword},'%'))
AND `dev`.`device_state` = 1
AND `dev`.`device_state` = 0
AND `iot_prod_info`.`prod_category_code` = #{query.prodCategoryCode}
AND `dev`.`area_id` LIKE CONCAT('%',#{query.areaId},'%')

mapper.select:
SELECT `dev`.`id` FROM `center_biz_device` `dev` LEFT JOIN `center_biz_tag_ref` `tag_ref` ON `tag_ref`.`business_key` = `dev`.`id`
`tag_ref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%',#{areaId},'%')

SELECT COUNT(`dev`.`id`) AS `totalNumber`, SUM(CASE WHEN `dev`.`device_state` = 0 THEN 1 ELSE 0 END) AS `offlineNumber`, SUM(CASE WHEN `dev`.`device_state` = 1 THEN 1 ELSE 0 END) AS `normalNumber` FROM `center_biz_device` `dev` INNER JOIN `center_biz_tag_ref` `tag_ref` ON `tag_ref`.`business_key` = `dev`.`id`
`tag_ref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%',#{areaId},'%')

SELECT COUNT(DISTINCT `a`.`tag_code`) FROM `center_biz_tag` `a` JOIN `center_biz_tag_ref` `b` ON `a`.`id` = `b`.`tag_id` JOIN ( SELECT `tagref`.`business_key` FROM `center_biz_device` `dev` JOIN `center_biz_tag_ref` `tagref` ON `dev`.`id` = `tagref`.`business_key`
`tagref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%',#{areaId},'%')
) `dev` ON `b`.`business_key` = `dev`.`business_key` WHERE `a`.`tag_code` LIKE CONCAT('builtin.app::', '%')

SELECT `dev`.`id` AS `deviceId`, `dev`.`device_code` AS `deviceCode`, `dev`.`device_name` AS `deviceName`, -- `icv`.`category_id` AS `genreId`, `dev`.`area_name` AS `areaName`, `dev`.`area_id` AS `areaId`, `dev`.`device_state` AS `deviceStatusCode`, `cbde`.`lnt_and_lat` AS `lntAndLat`, `dev`.`thirdparty_id` AS `thirdPartyId`, `dev`.`thirdparty_cfg` AS `thirdpartyCfg` FROM `center_biz_device` `dev` LEFT JOIN `center_biz_device_expand` `cbde` ON `dev`.`id` = `cbde`.`id` INNER JOIN `center_biz_tag_ref` `tag_ref` ON `tag_ref`.`business_key` = `dev`.`id`
`tag_ref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%', #{areaId}, '%')

SELECT `a`.`tag_code` AS `applicationCode`, COUNT(CASE WHEN `c`.`device_state` = '1' THEN 1 END) AS `normalNum`, COUNT(CASE WHEN `c`.`device_state` = '0' THEN 1 END) AS `offLineNum` FROM `center_biz_tag` `a` LEFT JOIN `center_biz_tag_ref` `b` ON `a`.`id` = `b`.`tag_id` LEFT JOIN `center_biz_device` `c` ON `b`.`business_key` = `c`.`id` JOIN ( SELECT `tagref`.`business_key` FROM `center_biz_device` `dev` JOIN `center_biz_tag_ref` `tagref` ON `dev`.`id` = `tagref`.`business_key`
`tagref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%', #{areaId}, '%')
) `dev` ON `b`.`business_key` = `dev`.`business_key` WHERE `a`.`tag_code` LIKE CONCAT('builtin.app::', '%') GROUP BY `a`.`tag_code`

SELECT COUNT(1) AS `num`, COUNT(`offLineId`) AS `offLineNum`, COUNT(`onLineId`) AS `onLineNum` FROM `center_biz_device` `dev` LEFT JOIN ( SELECT `id` AS `offLineId` FROM `center_biz_device` WHERE `device_state` = 0 ) `ofl` ON `ofl`.`offLineId` = `dev`.`id` LEFT JOIN ( SELECT `id` AS `onLineId` FROM `center_biz_device` WHERE `device_state` = 1 ) `ol` ON `ol`.`onLineId` = `dev`.`id` INNER JOIN `center_biz_tag_ref` `tag_ref` ON `tag_ref`.`business_key` = `dev`.`id`
`tag_ref`.`tag_id` = #{tagId}
AND `dev`.`area_id` LIKE CONCAT('%', #{areaId}, '%')
